//! Safe Rust bindings for kylin-genai-nlp SDK.
//!
//! Uses [`libloading`] to load `libkysdk-genai-nlp.so` at runtime.
//! Type definitions are generated by bindgen.
//!
//! # Library search order
//!
//! 1. `KART_SDK_PATH` environment variable (full path to .so)
//! 2. `<workspace>/crates/kart-nlp-sys/vendor/lib/libkysdk-genai-nlp.so`
//! 3. System library path (`/usr/lib/...`)
//! 4. `./libkysdk-genai-nlp.so` (next to the binary)
//!
//! # Safety
//!
//! This crate is the **only** place where `unsafe` is permitted for this SDK.
//! All `unsafe` is confined to `extern "C"` call sites.
//! The public API is fully safe Rust.

use std::ffi::{CStr, CString};
use std::os::raw::{c_char, c_void};
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, OnceLock};

use libloading::{Library, Symbol};
use thiserror::Error;
use tokio::sync::mpsc;

// Re-export types from bindgen
#[cfg(not(feature = "stub"))]
#[allow(nonstandard_style, unused)]
mod bindings;

#[cfg(not(feature = "stub"))]
pub use bindings::{
    ChatMessage, ChatModelConfig, ChatResult, ChatResultCallback, ChatResultSearchInfo,
    ChatResultSearchItem, GenAiTextInitCallback, GenAiTextSession, GenAiToolChoiceConfig,
    GenAiToolChoiceMode, GenAiToolHandler, GenAiToolType, ModelDeployType, PromptId, TextModelInfo,
    TextModelList,
};

// ── Error Types ─────────────────────────────────────────────────────────────

/// Errors returned by kylin-nlp operations.
#[derive(Debug, Error)]
pub enum KylinNlpError {
    /// SDK library not found or failed to load.
    #[error("kylin-genai-nlp SDK not found — set KART_SDK_PATH or install the SDK")]
    LibraryNotFound,

    /// Session initialization failed.
    #[error("Session initialization failed (code {0})")]
    InitFailed(i32),

    /// Chat request failed.
    #[error("Chat request failed: {0}")]
    ChatFailed(String),

    /// Invalid input (e.g., null bytes in string).
    #[error("Invalid input: {0}")]
    InvalidInput(String),

    /// SDK returned an error code.
    #[error("SDK error (code {0}): {1}")]
    SdkError(i32, String),

    /// Function not found in library.
    #[error("Function not found in library: {0}")]
    FunctionNotFound(String),
}

pub type Result<T> = std::result::Result<T, KylinNlpError>;

// ── Streaming Chunk ─────────────────────────────────────────────────────────

/// A chunk of streaming data from the SDK.
#[derive(Debug, Clone)]
pub struct StreamChunk {
    /// Text delta for this chunk.
    pub text: Option<String>,
    /// Reasoning/thinking content (chain-of-thought).
    pub reasoning: Option<String>,
    /// Whether this is the final chunk.
    pub is_final: bool,
    /// Error code (0 means success).
    pub error_code: i32,
    /// Human-readable error message.
    pub error_message: Option<String>,
}

// ── Callback Context ─────────────────────────────────────────────────────────

/// Context passed to the C callback for streaming results.
struct CallbackContext {
    /// TX channel for streaming chunks to async world.
    tx: mpsc::UnboundedSender<StreamChunk>,
    /// Set to true when KylinNlpSession is being dropped, signaling
    /// callbacks to reject their result. Prevents use-after-free when
    /// pending D-Bus callbacks fire after session destruction begins.
    dropping: AtomicBool,
}

/// Tool call result from the SDK.
#[derive(Debug, Clone)]
pub struct ToolCallResult {
    /// JSON array string of tool calls.
    pub tools_json: String,
}

/// Context passed to the C callback for tool results.
struct ToolCallbackContext {
    /// TX channel for tool call results to async world.
    tx: mpsc::UnboundedSender<ToolCallResult>,
    /// Same dropping flag as CallbackContext — see there for explanation.
    dropping: AtomicBool,
}

// ── Library Loading ──────────────────────────────────────────────────────────

static KYLIN_NLP_LIB: OnceLock<Option<Library>> = OnceLock::new();

fn lib() -> Option<&'static Library> {
    KYLIN_NLP_LIB
        .get_or_init(|| {
            // Debian/Kylin multiarch layout: /usr/lib/<triple>/. Pick the
            // triple matching the build target at compile time so we only try
            // the path that can actually exist on this binary's architecture.
            #[cfg(target_arch = "x86_64")]
            const SYSTEM_LIB: &str = "/usr/lib/x86_64-linux-gnu/libkysdk-genai-nlp.so";
            #[cfg(target_arch = "aarch64")]
            const SYSTEM_LIB: &str = "/usr/lib/aarch64-linux-gnu/libkysdk-genai-nlp.so";
            #[cfg(not(any(target_arch = "x86_64", target_arch = "aarch64")))]
            const SYSTEM_LIB: &str = "";

            let candidates: Vec<PathBuf> = vec![
                // 1. Explicit env-var override (full path)
                std::env::var("KART_SDK_PATH")
                    .ok()
                    .map(PathBuf::from)
                    .unwrap_or_default(),
                // 2. System library — multiarch path for this build target
                PathBuf::from(SYSTEM_LIB),
                // 3. Next to the running binary (deployment)
                std::env::current_exe()
                    .ok()
                    .and_then(|e| e.parent().map(|d| d.join("libkysdk-genai-nlp.so")))
                    .unwrap_or_default(),
                // 4. Bare SONAME — defers to the dynamic linker (ldconfig cache,
                //    LD_LIBRARY_PATH, etc.). Safety net for unusual install
                //    locations or architectures not covered above.
                PathBuf::from("libkysdk-genai-nlp.so"),
            ];

            for path in &candidates {
                if path.as_os_str().is_empty() {
                    continue;
                }
                match unsafe { Library::new(path) } {
                    Ok(lib) => {
                        // Verify library exports expected symbols
                        let valid = unsafe {
                            lib.get::<unsafe extern "C" fn() -> *mut GenAiTextSession>(
                                b"genai_text_create_session\0",
                            )
                            .is_ok()
                        };
                        if valid {
                            eprintln!("[kart-nlp-sys] loaded library from {}", path.display());
                            return Some(lib);
                        } else {
                            eprintln!(
                                "[kart-nlp-sys] {} loaded but symbols not found — not a valid SDK",
                                path.display()
                            );
                        }
                    }
                    Err(e) => {
                        eprintln!("[kart-nlp-sys] could not load {}: {}", path.display(), e);
                    }
                }
            }
            eprintln!(
                "[kart-nlp-sys] no library found; set KART_SDK_PATH or install the SDK"
            );
            None
        })
        .as_ref()
}

// ── C Callback Bridge ────────────────────────────────────────────────────────

/// C-compatible callback wrapper.
///
/// # Safety
/// This function is called from C code. The user_data must be a valid
/// pointer to a CallbackContext.
unsafe extern "C" fn chat_result_callback(result: *mut ChatResult, user_data: *mut c_void) {
    if user_data.is_null() {
        return;
    }

    let ctx = unsafe { &*(user_data as *const CallbackContext) };

    // Reject callbacks that fire after Drop has started. The SDK's GLib
    // event loop may have pending D-Bus signals that arrive after
    // g_dbus_connection_signal_unsubscribe is called in the C++ destructor.
    if ctx.dropping.load(Ordering::Acquire) {
        return;
    }

    if let Some(lib) = lib() {
        // Get assistant message
        let get_assistant: Symbol<unsafe extern "C" fn(*mut ChatResult) -> *const c_char> = unsafe {
            match lib.get(b"chat_result_get_assistant_message\0") {
                Ok(f) => f,
                Err(_) => return,
            }
        };

        // Get reasoning message
        let get_reasoning: Symbol<unsafe extern "C" fn(*mut ChatResult) -> *const c_char> = unsafe {
            match lib.get(b"chat_result_get_reasoning_message\0") {
                Ok(f) => f,
                Err(_) => return,
            }
        };

        // Get is_end
        let get_is_end: Symbol<unsafe extern "C" fn(*mut ChatResult) -> bool> = unsafe {
            match lib.get(b"chat_result_get_is_end\0") {
                Ok(f) => f,
                Err(_) => return,
            }
        };

        // Get error code
        let get_error_code: Symbol<unsafe extern "C" fn(*mut ChatResult) -> i32> = unsafe {
            match lib.get(b"chat_result_get_error_code\0") {
                Ok(f) => f,
                Err(_) => return,
            }
        };

        // Get error message
        let get_error_msg: Symbol<unsafe extern "C" fn(*mut ChatResult) -> *const c_char> = unsafe {
            match lib.get(b"chat_result_get_error_message\0") {
                Ok(f) => f,
                Err(_) => return,
            }
        };

        let text = unsafe {
            let ptr = get_assistant(result);
            if !ptr.is_null() {
                CStr::from_ptr(ptr).to_str().ok().map(String::from)
            } else {
                None
            }
        };

        let reasoning = unsafe {
            let ptr = get_reasoning(result);
            if !ptr.is_null() {
                CStr::from_ptr(ptr).to_str().ok().map(String::from)
            } else {
                None
            }
        };

        let is_final = unsafe { get_is_end(result) };
        let error_code = unsafe { get_error_code(result) };
        let error_message = unsafe {
            let ptr = get_error_msg(result);
            if !ptr.is_null() {
                CStr::from_ptr(ptr).to_str().ok().map(String::from)
            } else {
                None
            }
        };

        let chunk = StreamChunk {
            text,
            reasoning,
            is_final,
            error_code,
            error_message,
        };

        // Send to async world (ignore errors if receiver dropped)
        let _ = ctx.tx.send(chunk);
    }
}

/// C-compatible tool callback wrapper.
///
/// # Safety
/// This function is called from C code. The user_data must be a valid
/// pointer to a ToolCallbackContext.
unsafe extern "C" fn tool_result_callback(tools_json: *const c_char, user_data: *mut c_void) {
    if user_data.is_null() {
        return;
    }

    let ctx = unsafe { &*(user_data as *const ToolCallbackContext) };

    // Same dropping guard as chat_result_callback — see there for explanation.
    if ctx.dropping.load(Ordering::Acquire) {
        return;
    }

    let json_str = if !tools_json.is_null() {
        unsafe { CStr::from_ptr(tools_json).to_str().ok().map(String::from) }
    } else {
        None
    };

    if let Some(json) = json_str {
        let result = ToolCallResult { tools_json: json };
        let _ = ctx.tx.send(result);
    } else {
        tracing::warn!("tool_result_callback: received null tools_json from SDK");
    }
}

// ── Chat Message Helper ──────────────────────────────────────────────────────

/// Helper type for chat messages.
#[derive(Debug, Clone)]
pub struct ChatMessageData {
    pub role: String,
    pub content: String,
}

// ── Session Handle (RAII) ─────────────────────────────────────────────────────

/// Safe RAII handle over the SDK session.
///
/// Automatically destroys the session on `Drop`.
///
/// # Callback lifetime
///
/// The C SDK holds a raw pointer to `CallbackContext` for as long as it might
/// fire the callback.  We use `Arc` so that both `callback_ctx` (the Rust
/// owner) and `callback_raw` (the C pointer, derived from a cloned Arc) keep
/// the allocation alive independently.
///
/// When re-registering callbacks we first reclaim the old `callback_raw` via
/// `Arc::from_raw` (decrementing the C-side refcount) before updating the
/// fields.  In `Drop` the session is destroyed first (stopping all callbacks),
/// then any remaining raw pointers are reclaimed to avoid memory leaks.
pub struct KylinNlpSession {
    session: *mut GenAiTextSession,
    /// Rust-side Arc that owns the callback context allocation.
    callback_ctx: Option<Arc<CallbackContext>>,
    /// Raw pointer derived from a cloned Arc and passed to C.
    /// Must be reclaimed via `Arc::from_raw` before the allocation can be freed.
    callback_raw: *const CallbackContext,
    /// Rust-side Arc that owns the tool-callback context allocation.
    tool_callback_ctx: Option<Arc<ToolCallbackContext>>,
    /// Raw pointer for the tool callback (same semantics as `callback_raw`).
    tool_callback_raw: *const ToolCallbackContext,
}

impl KylinNlpSession {
    /// Create a new session.
    pub fn new() -> Result<Self> {
        let lib = lib().ok_or(KylinNlpError::LibraryNotFound)?;

        let session: *mut GenAiTextSession = unsafe {
            let f: Symbol<unsafe extern "C" fn() -> *mut GenAiTextSession> = lib
                .get(b"genai_text_create_session\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            f()
        };

        if session.is_null() {
            tracing::error!("genai_text_create_session returned null");
            return Err(KylinNlpError::InitFailed(-1));
        }

        tracing::debug!("KylinNlpSession created successfully");

        Ok(Self {
            session,
            callback_ctx: None,
            callback_raw: std::ptr::null(),
            tool_callback_ctx: None,
            tool_callback_raw: std::ptr::null(),
        })
    }

    /// Initialize the session.
    pub fn init(&mut self) -> Result<()> {
        let lib = lib().ok_or(KylinNlpError::LibraryNotFound)?;

        let ret: i32 = unsafe {
            let f: Symbol<unsafe extern "C" fn(*mut GenAiTextSession) -> i32> = lib
                .get(b"genai_text_init_session\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            f(self.session)
        };

        if ret != 0 {
            Err(KylinNlpError::InitFailed(ret))
        } else {
            Ok(())
        }
    }

    /// Set model configuration.
    pub fn set_model(&mut self, model_name: &str, temperature: f64) -> Result<()> {
        let lib = lib().ok_or(KylinNlpError::LibraryNotFound)?;

        let model_cstr =
            CString::new(model_name).map_err(|e| KylinNlpError::InvalidInput(e.to_string()))?;

        unsafe {
            // Create config
            let create_config: Symbol<unsafe extern "C" fn() -> *mut ChatModelConfig> = lib
                .get(b"chat_model_config_create\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            let config = create_config();

            if config.is_null() {
                return Err(KylinNlpError::ChatFailed(
                    "Failed to create config".to_string(),
                ));
            }

            // Set model name
            let set_name: Symbol<unsafe extern "C" fn(*mut ChatModelConfig, *const c_char)> = lib
                .get(b"chat_model_config_set_name\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            set_name(config, model_cstr.as_ptr());

            // Set temperature
            let set_temp: Symbol<unsafe extern "C" fn(*mut ChatModelConfig, f64) -> i32> = lib
                .get(b"chat_model_config_set_temperature\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            set_temp(config, temperature);

            // Apply config to session
            let set_config: Symbol<
                unsafe extern "C" fn(*mut GenAiTextSession, *mut ChatModelConfig),
            > = lib
                .get(b"genai_text_set_model_config\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            set_config(self.session, config);

            // Destroy config
            let destroy_config: Symbol<unsafe extern "C" fn(*mut *mut ChatModelConfig)> = lib
                .get(b"chat_model_config_destroy\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            let mut config_ptr = config;
            destroy_config(&mut config_ptr);
        }

        Ok(())
    }

    /// Set system prompt.
    pub fn set_system_prompt(&mut self, prompt: &str) -> Result<()> {
        let lib = lib().ok_or(KylinNlpError::LibraryNotFound)?;

        let prompt_cstr =
            CString::new(prompt).map_err(|e| KylinNlpError::InvalidInput(e.to_string()))?;

        unsafe {
            let f: Symbol<unsafe extern "C" fn(*mut GenAiTextSession, *const c_char)> = lib
                .get(b"genai_text_set_chat_system_prompt\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            f(self.session, prompt_cstr.as_ptr());
        }

        Ok(())
    }

    /// Chat with streaming results.
    ///
    /// Returns a receiver that yields chunks as they arrive.
    pub fn chat_stream(&mut self, message: &str) -> Result<mpsc::UnboundedReceiver<StreamChunk>> {
        let lib = lib().ok_or(KylinNlpError::LibraryNotFound)?;

        let (tx, rx) = mpsc::unbounded_channel();

        // Build an Arc for the context.  We give C a raw pointer derived from a
        // *clone* so C holds its own refcount.  The original Arc is stored in
        // `self.callback_ctx` as the Rust-side owner.
        let ctx = Arc::new(CallbackContext { tx, dropping: AtomicBool::new(false) });
        let raw = Arc::into_raw(Arc::clone(&ctx));

        // Reclaim any previous raw ptr we gave to C (its refcount drop) before
        // replacing self.callback_ctx below.
        if !self.callback_raw.is_null() {
            unsafe { drop(Arc::from_raw(self.callback_raw)); }
        }

        // Register callback
        unsafe {
            let set_callback: Symbol<
                unsafe extern "C" fn(*mut GenAiTextSession, ChatResultCallback, *mut c_void),
            > = lib
                .get(b"genai_text_result_set_callback\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            set_callback(self.session, Some(chat_result_callback), raw as *mut c_void);
        }

        // Enable internal event loop (so callbacks fire without GLib)
        unsafe {
            let enable_loop: Symbol<unsafe extern "C" fn(*mut GenAiTextSession, bool)> = lib
                .get(b"genai_text_enable_internal_event_loop\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            enable_loop(self.session, true);
        }

        // Send chat request
        let message_cstr =
            CString::new(message).map_err(|e| KylinNlpError::InvalidInput(e.to_string()))?;

        unsafe {
            let chat: Symbol<unsafe extern "C" fn(*mut GenAiTextSession, *const c_char)> = lib
                .get(b"genai_text_chat_async\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            chat(self.session, message_cstr.as_ptr());
        }

        self.callback_ctx = Some(ctx);
        self.callback_raw = raw;

        Ok(rx)
    }

    /// Chat with history messages.
    pub fn chat_with_history(
        &mut self,
        messages: &[ChatMessageData],
    ) -> Result<mpsc::UnboundedReceiver<StreamChunk>> {
        let lib = lib().ok_or(KylinNlpError::LibraryNotFound)?;

        let (tx, rx) = mpsc::unbounded_channel();

        // Same Arc/raw pattern as chat_stream — see its comments.
        let ctx = Arc::new(CallbackContext { tx, dropping: AtomicBool::new(false) });
        let raw = Arc::into_raw(Arc::clone(&ctx));

        if !self.callback_raw.is_null() {
            unsafe { drop(Arc::from_raw(self.callback_raw)); }
        }

        // Register callback
        unsafe {
            let set_callback: Symbol<
                unsafe extern "C" fn(*mut GenAiTextSession, ChatResultCallback, *mut c_void),
            > = lib
                .get(b"genai_text_result_set_callback\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            set_callback(self.session, Some(chat_result_callback), raw as *mut c_void);
        }

        // Enable internal event loop
        unsafe {
            let enable_loop: Symbol<unsafe extern "C" fn(*mut GenAiTextSession, bool)> = lib
                .get(b"genai_text_enable_internal_event_loop\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            enable_loop(self.session, true);
        }

        // Build history messages
        unsafe {
            let create_msg: Symbol<unsafe extern "C" fn() -> *mut ChatMessage> = lib
                .get(b"chat_message_create\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            let add_system: Symbol<unsafe extern "C" fn(*mut ChatMessage, *const c_char)> = lib
                .get(b"chat_message_add_system_message\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            let add_user: Symbol<unsafe extern "C" fn(*mut ChatMessage, *const c_char)> = lib
                .get(b"chat_message_add_user_message\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            let add_assistant: Symbol<unsafe extern "C" fn(*mut ChatMessage, *const c_char)> = lib
                .get(b"chat_message_add_assistant_message\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            let chat_history: Symbol<
                unsafe extern "C" fn(*mut GenAiTextSession, *mut ChatMessage),
            > = lib
                .get(b"genai_text_chat_with_history_messages_async\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            let destroy_msg: Symbol<unsafe extern "C" fn(*mut *mut ChatMessage)> = lib
                .get(b"chat_message_destroy\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;

            let history = create_msg();

            for msg in messages {
                let content_cstr = CString::new(msg.content.as_str())
                    .map_err(|e| KylinNlpError::InvalidInput(e.to_string()))?;

                match msg.role.as_str() {
                    "system" => add_system(history, content_cstr.as_ptr()),
                    "user" => add_user(history, content_cstr.as_ptr()),
                    "assistant" => add_assistant(history, content_cstr.as_ptr()),
                    _ => {
                        // "tool" role messages are not supported by the SDK history API.
                        // They are handled via the submit_tool_result() mechanism instead.
                    }
                }
            }

            chat_history(self.session, history);
            let mut history_ptr = history;
            destroy_msg(&mut history_ptr);
        }

        self.callback_ctx = Some(ctx);
        self.callback_raw = raw;

        Ok(rx)
    }

    /// Re-register the chat result callback with a fresh channel.
    ///
    /// Call this after `submit_tool_result()` to receive the model's
    /// continued response on a new receiver.
    pub fn re_register_chat_callback(
        &mut self,
    ) -> Result<mpsc::UnboundedReceiver<StreamChunk>> {
        let lib = lib().ok_or(KylinNlpError::LibraryNotFound)?;

        let (tx, rx) = mpsc::unbounded_channel();

        let ctx = Arc::new(CallbackContext { tx, dropping: AtomicBool::new(false) });
        let raw = Arc::into_raw(Arc::clone(&ctx));

        // Reclaim the refcount we previously gave to C for the old callback.
        // This is safe here because re_register is only called after the prior
        // chat operation has fully completed (all chunks drained from the old rx).
        if !self.callback_raw.is_null() {
            unsafe { drop(Arc::from_raw(self.callback_raw)); }
        }

        unsafe {
            let set_callback: Symbol<
                unsafe extern "C" fn(*mut GenAiTextSession, ChatResultCallback, *mut c_void),
            > = lib
                .get(b"genai_text_result_set_callback\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            set_callback(self.session, Some(chat_result_callback), raw as *mut c_void);
        }

        self.callback_ctx = Some(ctx);
        self.callback_raw = raw;

        Ok(rx)
    }

    /// Re-register the tool handler callback with a fresh channel.
    ///
    /// Call this after `submit_tool_result()` to receive any further
    /// tool call requests from the model.
    pub fn re_register_tool_handler(
        &mut self,
    ) -> Result<mpsc::UnboundedReceiver<ToolCallResult>> {
        let lib = lib().ok_or(KylinNlpError::LibraryNotFound)?;

        let (tx, rx) = mpsc::unbounded_channel();

        let ctx = Arc::new(ToolCallbackContext { tx, dropping: AtomicBool::new(false) });
        let raw = Arc::into_raw(Arc::clone(&ctx));

        // Same reclamation pattern as re_register_chat_callback.
        if !self.tool_callback_raw.is_null() {
            unsafe { drop(Arc::from_raw(self.tool_callback_raw)); }
        }

        unsafe {
            let f: Symbol<
                unsafe extern "C" fn(*mut GenAiTextSession, GenAiToolHandler, *mut c_void),
            > = lib
                .get(b"genai_text_set_tool_handler\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            f(self.session, Some(tool_result_callback), raw as *mut c_void);
        }

        self.tool_callback_ctx = Some(ctx);
        self.tool_callback_raw = raw;

        Ok(rx)
    }

    /// Stop current chat.
    pub fn stop_chat(&mut self) -> Result<()> {
        let lib = lib().ok_or(KylinNlpError::LibraryNotFound)?;

        unsafe {
            let f: Symbol<unsafe extern "C" fn(*mut GenAiTextSession)> = lib
                .get(b"genai_text_stop_chat\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            f(self.session);
        }

        Ok(())
    }

    /// Clear chat history.
    pub fn clear_history(&mut self) -> Result<()> {
        let lib = lib().ok_or(KylinNlpError::LibraryNotFound)?;

        unsafe {
            let f: Symbol<unsafe extern "C" fn(*mut GenAiTextSession)> = lib
                .get(b"genai_text_clear_chat_history_messages\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            f(self.session);
        }

        Ok(())
    }

    /// Set up tool handler and return a receiver for tool call results.
    ///
    /// When the model requests a tool, the result will be sent through the returned channel.
    pub fn set_tool_handler(&mut self) -> Result<mpsc::UnboundedReceiver<ToolCallResult>> {
        let lib = lib().ok_or(KylinNlpError::LibraryNotFound)?;

        let (tx, rx) = mpsc::unbounded_channel();

        let ctx = Arc::new(ToolCallbackContext { tx, dropping: AtomicBool::new(false) });
        let raw = Arc::into_raw(Arc::clone(&ctx));

        if !self.tool_callback_raw.is_null() {
            unsafe { drop(Arc::from_raw(self.tool_callback_raw)); }
        }

        // Register tool handler
        unsafe {
            let f: Symbol<
                unsafe extern "C" fn(*mut GenAiTextSession, GenAiToolHandler, *mut c_void),
            > = lib
                .get(b"genai_text_set_tool_handler\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            f(self.session, Some(tool_result_callback), raw as *mut c_void);
        }

        self.tool_callback_ctx = Some(ctx);
        self.tool_callback_raw = raw;

        Ok(rx)
    }

    /// Register a tool so the model can call it.
    pub fn register_tool(&mut self, name: &str, json_schema: &str) -> Result<()> {
        let lib = lib().ok_or(KylinNlpError::LibraryNotFound)?;

        let name_cstr =
            CString::new(name).map_err(|e| KylinNlpError::InvalidInput(e.to_string()))?;
        let schema_cstr =
            CString::new(json_schema).map_err(|e| KylinNlpError::InvalidInput(e.to_string()))?;

        unsafe {
            let f: Symbol<
                unsafe extern "C" fn(
                    *mut GenAiTextSession,
                    *const c_char,
                    GenAiToolType,
                    *const c_char,
                ) -> i32,
            > = lib
                .get(b"genai_text_register_tool\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            let ret = f(self.session, name_cstr.as_ptr(), 0u32 as GenAiToolType, schema_cstr.as_ptr());
            if ret != 0 {
                tracing::error!("register_tool failed for {}: ret={}", name, ret);
                return Err(KylinNlpError::SdkError(ret, format!("register_tool failed for {}", name)));
            }
        }

        Ok(())
    }

    /// Create a tool choice configuration.
    pub fn create_tool_choice_config(mode: GenAiToolChoiceMode) -> Result<*mut GenAiToolChoiceConfig> {
        let lib = lib().ok_or(KylinNlpError::LibraryNotFound)?;

        let config: *mut GenAiToolChoiceConfig = unsafe {
            let f: Symbol<
                unsafe extern "C" fn(GenAiToolChoiceMode) -> *mut GenAiToolChoiceConfig,
            > = lib
                .get(b"genai_text_create_tool_choice_config\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            f(mode)
        };

        if config.is_null() {
            return Err(KylinNlpError::ChatFailed(
                "Failed to create tool choice config".to_string(),
            ));
        }

        Ok(config)
    }

    /// Set the tool choice configuration on the session.
    pub fn set_tool_choice_config(&mut self, config: *const GenAiToolChoiceConfig) -> Result<()> {
        let lib = lib().ok_or(KylinNlpError::LibraryNotFound)?;

        unsafe {
            let f: Symbol<
                unsafe extern "C" fn(*mut GenAiTextSession, *const GenAiToolChoiceConfig),
            > = lib
                .get(b"genai_text_set_tool_choice_config\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            f(self.session, config);
        }

        Ok(())
    }

    /// Set a specific tool to be forced in tool choice configuration.
    ///
    /// After creating a config with `create_tool_choice_config`, call this to
    /// force the model to use a specific tool instead of auto-selecting.
    pub fn tool_choice_config_set_specific_tool(
        config: *mut GenAiToolChoiceConfig,
        tool_name: &str,
    ) -> Result<()> {
        let lib = lib().ok_or(KylinNlpError::LibraryNotFound)?;

        let name_cstr =
            CString::new(tool_name).map_err(|e| KylinNlpError::InvalidInput(e.to_string()))?;

        unsafe {
            let f: Symbol<
                unsafe extern "C" fn(*mut GenAiToolChoiceConfig, *const c_char),
            > = lib
                .get(b"genai_text_tool_choice_config_set_specific_tool\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            f(config, name_cstr.as_ptr());
        }

        Ok(())
    }

    /// Destroy a tool choice configuration.
    pub fn destroy_tool_choice_config(config: *mut *mut GenAiToolChoiceConfig) -> Result<()> {
        let lib = lib().ok_or(KylinNlpError::LibraryNotFound)?;

        unsafe {
            let f: Symbol<unsafe extern "C" fn(*mut *mut GenAiToolChoiceConfig)> = lib
                .get(b"genai_text_destroy_tool_choice_config\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            f(config);
        }

        Ok(())
    }

    /// Submit tool execution result to the SDK.
    pub fn submit_tool_result(&mut self, tool_calls_json: &str, result_json: &str) -> Result<()> {
        let lib = lib().ok_or(KylinNlpError::LibraryNotFound)?;

        tracing::debug!(
            tool_calls_len = tool_calls_json.len(),
            tool_calls_preview = %&tool_calls_json[..tool_calls_json.len().min(200)],
            result_len = result_json.len(),
            result_preview = %&result_json[..result_json.len().min(200)],
            "submit_tool_result called"
        );

        let calls_cstr = CString::new(tool_calls_json)
            .map_err(|e| KylinNlpError::InvalidInput(e.to_string()))?;
        let result_cstr = CString::new(result_json)
            .map_err(|e| KylinNlpError::InvalidInput(e.to_string()))?;

        unsafe {
            let f: Symbol<
                unsafe extern "C" fn(
                    *mut GenAiTextSession,
                    *const c_char,
                    *const c_char,
                ) -> i32,
            > = lib
                .get(b"genai_text_submit_tool_result\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            let ret = f(self.session, calls_cstr.as_ptr(), result_cstr.as_ptr());
            if ret != 0 {
                tracing::error!("submit_tool_result SDK returned ret={}", ret);
                return Err(KylinNlpError::SdkError(
                    ret,
                    "submit_tool_result failed".to_string(),
                ));
            }
        }

        tracing::debug!("submit_tool_result SDK call succeeded");

        Ok(())
    }
}

impl Drop for KylinNlpSession {
    fn drop(&mut self) {
        // Set dropping flag BEFORE destroying the session, so any pending
        // D-Bus callbacks that have already dispatched see the flag and bail out
        // instead of accessing freed memory.
        if let Some(ctx) = self.callback_ctx.as_ref() {
            ctx.dropping.store(true, Ordering::Release);
        }
        if let Some(ctx) = self.tool_callback_ctx.as_ref() {
            ctx.dropping.store(true, Ordering::Release);
        }

        // Destroy the session first — this stops the C SDK from firing any
        // further callbacks, making it safe to reclaim the raw Arc refs below.
        if let Some(lib) = lib() {
            unsafe {
                if let Ok(f) = lib.get::<unsafe extern "C" fn(*mut *mut GenAiTextSession)>(
                    b"genai_text_destroy_session\0",
                ) {
                    f(&mut self.session);
                }
            }
        }
        // IMPORTANT: clear self.callback_ctx FIRST so the channel tx is dropped
        // before we reclaim the Arc refcounts. This ordering is critical:
        //   1. self.callback_ctx = None   → tx (UnboundedSender) is dropped here
        //   2. Arc::from_raw(reclaim)    → only the Arc wrapper is freed, not tx
        // If we reclaim the Arc before setting None, a concurrent GLib callback
        // may hold a stale Arc and try to send() on a tx that is already Dropped.
        self.callback_ctx = None;
        self.tool_callback_ctx = None;

        // Now reclaim the extra Arc refcounts we handed to C.
        if !self.callback_raw.is_null() {
            unsafe { drop(Arc::from_raw(self.callback_raw)); }
            self.callback_raw = std::ptr::null();
        }
        if !self.tool_callback_raw.is_null() {
            unsafe { drop(Arc::from_raw(self.tool_callback_raw)); }
            self.tool_callback_raw = std::ptr::null();
        }
    }
}

// Make session Send + Sync safe (SDK handles its own thread safety)
unsafe impl Send for KylinNlpSession {}
unsafe impl Sync for KylinNlpSession {}

/// Deployment type for a model, returned by the NLP SDK.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u32)]
pub enum DeployType {
    OnDevice = 0,
    PublicCloud = 1,
    PrivateCloud = 2,
}

impl From<ModelDeployType> for DeployType {
    fn from(v: ModelDeployType) -> Self {
        match v {
            0 => DeployType::OnDevice,
            1 => DeployType::PublicCloud,
            2 => DeployType::PrivateCloud,
            _ => DeployType::OnDevice,
        }
    }
}

/// Model information returned by `get_model_list`.
#[derive(Debug, Clone)]
pub struct KartModelInfo {
    /// Canonical model identifier, e.g. "qwen2.5-7b-instruct".
    pub model_name: String,
    /// Human-readable display name, e.g. "Qwen2.5 7B Instruct".
    pub display_name: String,
    /// Deployment type of the model.
    pub deploy_type: DeployType,
    /// Whether the model supports web search.
    pub supports_web_search: bool,
    /// Whether the model supports thinking/reasoning.
    pub supports_thinking: bool,
    /// Whether thinking can be toggled per request.
    pub supports_thinking_toggle: bool,
    /// Brand name, e.g. "Qwen", "Kylin".
    pub brand: String,
    /// Whether the model supports tool choice.
    pub supports_tool_choice: bool,
}

/// Extract a UTF-8 string from a pointer returned by a C function, or empty string on null/error.
unsafe fn get_str(lib: &Library, symbol: &[u8], model_info: *const TextModelInfo) -> String {
    let mut err: i32 = 0;
    let ptr: *const c_char = {
        let f: Symbol<unsafe extern "C" fn(*const TextModelInfo, *mut i32) -> *const c_char> =
            match lib.get(symbol) {
                Ok(f) => f,
                Err(_) => return String::new(),
            };
        f(model_info, &mut err)
    };
    if ptr.is_null() || err != 0 {
        return String::new();
    }
    if let Ok(s) = CStr::from_ptr(ptr).to_str() {
        s.to_string()
    } else {
        String::new()
    }
}

/// Get the list of available models from the SDK.
pub fn get_model_list() -> Result<Vec<KartModelInfo>> {
    let lib = lib().ok_or(KylinNlpError::LibraryNotFound)?;

    // Create a temporary session just to call get_model_list
    let mut session: *mut GenAiTextSession = unsafe {
        let f: Symbol<unsafe extern "C" fn() -> *mut GenAiTextSession> = lib
            .get(b"genai_text_create_session\0")
            .map_err(|_| KylinNlpError::LibraryNotFound)?;
        f()
    };

    if session.is_null() {
        return Err(KylinNlpError::InitFailed(-1));
    }

    // Initialize the session (required before calling get_model_list)
    let init_result: i32 = unsafe {
        let f: Symbol<unsafe extern "C" fn(*mut GenAiTextSession) -> i32> = lib
            .get(b"genai_text_init_session\0")
            .map_err(|_| KylinNlpError::LibraryNotFound)?;
        f(session)
    };

    if init_result != 0 {
        return Err(KylinNlpError::InitFailed(init_result));
    }

    let mut error_code: i32 = 0;
    let model_list: *const TextModelList = unsafe {
        let f: Symbol<unsafe extern "C" fn(*mut GenAiTextSession, *mut i32) -> *const TextModelList> =
            lib.get(b"genai_text_get_model_list\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
        f(session, &mut error_code)
    };

    let models = if !model_list.is_null() {
        let count: i32 = unsafe {
            let f: Symbol<unsafe extern "C" fn(*const TextModelList) -> i32> = lib
                .get(b"genai_text_model_list_get_count\0")
                .map_err(|_| KylinNlpError::LibraryNotFound)?;
            f(model_list)
        };

        let mut result = Vec::new();
        for i in 0..count {
            let mut err: i32 = 0;
            let model_info: *const TextModelInfo = unsafe {
                let f: Symbol<
                    unsafe extern "C" fn(*const TextModelList, i32, *mut i32) -> *const TextModelInfo,
                > = lib
                    .get(b"genai_text_model_list_get_model_info\0")
                    .map_err(|_| KylinNlpError::LibraryNotFound)?;
                f(model_list, i, &mut err)
            };

            if !model_info.is_null() {
                let model_name = unsafe { get_str(&lib, b"genai_text_model_info_get_model_name\0", model_info) };
                let display_name = unsafe { get_str(&lib, b"genai_text_model_info_get_display_name\0", model_info) };
                let brand = unsafe { get_str(&lib, b"genai_text_model_info_get_brand\0", model_info) };

                let deploy_type: DeployType = unsafe {
                    let mut err: i32 = 0;
                    let f: Symbol<unsafe extern "C" fn(*const TextModelInfo, *mut i32) -> ModelDeployType> =
                        match lib.get(b"genai_text_model_info_get_deploy_type\0") {
                            Ok(f) => f,
                            Err(_) => continue,
                        };
                    f(model_info, &mut err).into()
                };

                let supports_web_search = unsafe {
                    let mut err: i32 = 0;
                    let f: Symbol<unsafe extern "C" fn(*const TextModelInfo, *mut i32) -> bool> =
                        match lib.get(b"genai_text_model_info_supports_web_search\0") {
                            Ok(f) => f,
                            Err(_) => continue,
                        };
                    f(model_info, &mut err)
                };

                let supports_thinking = unsafe {
                    let mut err: i32 = 0;
                    let f: Symbol<unsafe extern "C" fn(*const TextModelInfo, *mut i32) -> bool> =
                        match lib.get(b"genai_text_model_info_supports_thinking\0") {
                            Ok(f) => f,
                            Err(_) => continue,
                        };
                    f(model_info, &mut err)
                };

                let supports_thinking_toggle = unsafe {
                    let mut err: i32 = 0;
                    let f: Symbol<unsafe extern "C" fn(*const TextModelInfo, *mut i32) -> bool> =
                        match lib.get(b"genai_text_model_info_supports_thinking_toggle\0") {
                            Ok(f) => f,
                            Err(_) => continue,
                        };
                    f(model_info, &mut err)
                };

                let supports_tool_choice = unsafe {
                    let mut err: i32 = 0;
                    let f: Symbol<unsafe extern "C" fn(*const TextModelInfo, *mut i32) -> bool> =
                        match lib.get(b"genai_text_model_info_supports_tool_choice\0") {
                            Ok(f) => f,
                            Err(_) => continue,
                        };
                    f(model_info, &mut err)
                };

                result.push(KartModelInfo {
                    model_name,
                    display_name,
                    deploy_type,
                    supports_web_search,
                    supports_thinking,
                    supports_thinking_toggle,
                    brand,
                    supports_tool_choice,
                });
            }
        }
        result
    } else {
        Vec::new()
    };

    // Destroy the temporary session
    unsafe {
        let f: Symbol<unsafe extern "C" fn(*mut *mut GenAiTextSession)> = lib
            .get(b"genai_text_destroy_session\0")
            .map_err(|_| KylinNlpError::LibraryNotFound)?;
        f(&mut session as *mut *mut GenAiTextSession);
    }

    Ok(models)
}

/// Check if the SDK library is available.
pub fn is_available() -> bool {
    lib().is_some()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_is_available() {
        // This test will pass whether or not the SDK is installed
        let _ = is_available();
    }

    #[test]
    fn test_error_display() {
        let err = KylinNlpError::LibraryNotFound;
        assert!(err.to_string().contains("not found"));

        let err = KylinNlpError::InitFailed(-1);
        assert!(err.to_string().contains("-1"));
    }

    #[test]
    fn test_error_chat_failed() {
        let err = KylinNlpError::ChatFailed("timeout".into());
        assert!(err.to_string().contains("Chat request failed"));
        assert!(err.to_string().contains("timeout"));
    }

    #[test]
    fn test_error_invalid_input() {
        let err = KylinNlpError::InvalidInput("null byte".into());
        assert!(err.to_string().contains("Invalid input"));
        assert!(err.to_string().contains("null byte"));
    }

    #[test]
    fn test_error_sdk_error() {
        let err = KylinNlpError::SdkError(1001, "service unavailable".into());
        assert!(err.to_string().contains("SDK error"));
        assert!(err.to_string().contains("1001"));
        assert!(err.to_string().contains("service unavailable"));
    }

    #[test]
    fn test_error_function_not_found() {
        let err = KylinNlpError::FunctionNotFound("genai_text_chat".into());
        assert!(err.to_string().contains("Function not found"));
        assert!(err.to_string().contains("genai_text_chat"));
    }

    #[test]
    fn test_model_info_debug() {
        let info = KartModelInfo {
            model_name: "qwen2.5-7b".into(),
            display_name: "Qwen2.5 7B".into(),
            deploy_type: DeployType::OnDevice,
            supports_web_search: true,
            supports_thinking: false,
            supports_thinking_toggle: false,
            brand: "Qwen".into(),
            supports_tool_choice: true,
        };
        let debug = format!("{:?}", info);
        assert!(debug.contains("qwen2.5-7b"));
        assert!(debug.contains("Qwen2.5 7B"));
        assert!(debug.contains("Qwen"));
        assert!(debug.contains("OnDevice"));
    }

    #[test]
    fn test_get_model_list_returns_model_info() {
        let result = get_model_list();
        match result {
            Ok(models) => {
                assert!(!models.is_empty(), "expected at least one model");
                for model in models {
                    assert!(!model.model_name.is_empty(), "model_name should not be empty");
                    assert!(!model.display_name.is_empty(), "display_name should not be empty");
                    assert!(!model.brand.is_empty(), "brand should not be empty");
                    // deploy_type is already a proper DeployType enum, no raw comparison needed
                    // All boolean fields should be deterministically set
                    let _ = model.supports_web_search;
                    let _ = model.supports_thinking;
                    let _ = model.supports_thinking_toggle;
                    let _ = model.supports_tool_choice;
                }
            }
            Err(e) => {
                eprintln!("SDK not available: {}", e);
            }
        }
    }

    #[test]
    fn test_model_info_deploy_type_values() {
        let result = get_model_list();
        if let Ok(models) = result {
            for model in models {
                // Verify deploy_type is a valid enum variant
                match model.deploy_type {
                    DeployType::OnDevice | DeployType::PublicCloud | DeployType::PrivateCloud => {}
                }
            }
        }
    }

    #[test]
    fn test_model_info_model_name_is_valid() {
        let result = get_model_list();
        if let Ok(models) = result {
            for model in models {
                // Model names should not contain spaces (typically snake_case or dash-separated)
                // and should be non-empty
                assert!(!model.model_name.is_empty());
                assert!(!model.model_name.contains(char::is_whitespace) || model.model_name.contains(' '),
                    "model_name '{}' should be a valid identifier", model.model_name);
            }
        }
    }

    #[test]
    fn test_print_model_list_for_inspection() {
        let result = get_model_list();
        match result {
            Ok(models) => {
                println!("\n=== Model List ({} models) ===", models.len());
                for (i, model) in models.iter().enumerate() {
                    println!("\n[{}] {}", i, model.model_name);
                    println!("    display_name: {}", model.display_name);
                    println!("    brand: {}", model.brand);
                    println!("    deploy_type: {:?}", model.deploy_type);
                    println!("    supports_web_search: {}", model.supports_web_search);
                    println!("    supports_thinking: {}", model.supports_thinking);
                    println!("    supports_thinking_toggle: {}", model.supports_thinking_toggle);
                    println!("    supports_tool_choice: {}", model.supports_tool_choice);
                }
                println!("\n==============================");
            }
            Err(e) => {
                println!("SDK not available: {}", e);
            }
        }
    }
}
